import 'dart:io';import 'dart:convert';
import 'package:flutter/services.dart';import 'package:flutter_test/flutter_test.dart';
import '../lib/core/services/tafsir_service.dart';import '../lib/core/services/bundled_tafsir_source.dart';import '../lib/core/services/quran_repository.dart';
class DenyMuyassarHttp extends HttpOverrides{int calls=0;@override HttpClient createHttpClient(SecurityContext?c){calls++;throw StateError('Network denied');}}
void main(){TestWidgetsFlutterBinding.ensureInitialized();final deny=DenyMuyassarHttp();
 setUpAll((){HttpOverrides.global=deny;TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger.setMockMessageHandler('flutter/assets',(m)async{final f=File(utf8.decode(m!.buffer.asUint8List()));return f.existsSync()?ByteData.sublistView(f.readAsBytesSync()):null;});});tearDownAll((){HttpOverrides.global=null;TafsirService.setBundledSourceForTesting(null);QuranRepository.resetCachesForTesting();});
 test('all6236primary match repaired stores and439original plus94new witnesses exact offline',()async{
  final witness=jsonDecode(File('/tmp/offline-corpus-preparation/muyassar2012-whole.json').readAsStringSync());final witnessMap={for(final x in witness['contents'])x['related_ayahs'].toString().replaceAll(RegExp(r'-\d+$'),''):x};final changes=jsonDecode(File('/tmp/offline-corpus-preparation/muyassar-finite-439.json').readAsStringSync())as List;final keys={for(final x in changes)'${x['surah']}:${x['ayah']}'};final notices=(jsonDecode(File('assets/data/tafsir_muyassar_witness_manifest.json').readAsStringSync()) as Map)['sourceWarnings'] as Map;const repaired={'9:25','60:8','3:119','4:170','6:8','9:39','43:28','39:6','71:11'};var count=0,variants=0,originalVariants=0;
  for(var s=1;s<=114;s++)for(final row in jsonDecode(File('assets/data/surahs/$s.json').readAsStringSync())){
   final a=row['ayah_number'];final key='$s:$a';final result=await TafsirService.getTafsir(surahId:s,ayahNumber:a);expect(result.editionId,'muyassar');expect(result.hasSourceText,isTrue,reason:key);expect(result.sourcePages.first.text,row['tafseer'],reason:key);expect(result.sourcePages.first.sourceUrl,isNull);expect(result.sourceUrl,isNull);if(!repaired.contains(key))expect(result.sourcePages.first.sourceLabel,contains('دون تغيير'));
   if(notices.containsKey(key)&&key!='9:25'&&key!='60:8'){expect(result.sourcePages,hasLength(2));final original=witnessMap[key];expect(result.sourcePages.last.text,BundledTafsirSource.plain(original['text']),reason:key);expect(result.sourcePages.last.sourceId,original['id']);expect(result.sourcePages.last.sourceLabel,contains('اختلاف النسختين'));expect(result.sourceNotice,isNotNull);expect(result.formatForShare('سورة'),contains('اختلاف النسختين'));variants++;if(keys.contains(key))originalVariants++;}else{expect(result.sourcePages,hasLength(1));if(notices.containsKey(key)){expect(result.sourceNotice,contains('رقم دخيل'));}else{expect(result.sourceNotice,isNull);}}count++;
  }expect(count,6236);expect(originalVariants,439);expect(variants,533);expect(notices.length,535);expect(deny.calls,0);
 });
 test('changedMuyassarwitness checksum fails closed and does not fall back to unmarked primary',()async{
  final bad=BundledTafsirSource(readAsset:(p)async=>p.endsWith('_1_1.b64')?'AAAA':File(p).readAsStringSync());TafsirService.setBundledSourceForTesting(bad);final result=await TafsirService.getTafsir(surahId:1,ayahNumber:3);expect(result.hasSourceText,isFalse);expect(result.sourcePages,isEmpty);expect(result.tafsirText,contains('لا يُعرض نص بديل'));TafsirService.setBundledSourceForTesting(null);
 });
}
